using System;
using System.Diagnostics;
using System.Reflection;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace MyApp.Tests;

[AttributeUsage(AttributeTargets.Method, AllowMultiple = false)]
public sealed class TimedTestMethodAttribute : Attribute, ITestDataLifecycleCallbacks
{
    private readonly int _warningThresholdMs;
    private Stopwatch? _stopwatch;

    public TimedTestMethodAttribute(int warningThresholdMs = 5000)
    {
        _warningThresholdMs = warningThresholdMs;
    }

    public void OnTestDataStart(MethodInfo methodInfo)
    {
        _stopwatch = Stopwatch.StartNew();
    }

    public void OnTestDataEnd(MethodInfo methodInfo, TestResult[] results)
    {
        _stopwatch?.Stop();
        if (_stopwatch is not null && _stopwatch.ElapsedMilliseconds > _warningThresholdMs)
        {
            Console.WriteLine($"WARNING: {methodInfo.Name} took {_stopwatch.ElapsedMilliseconds}ms (threshold: {_warningThresholdMs}ms)");
        }
    }
}

